module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // Next-state and output logic (combinational)
    always_comb begin
        next_state = state;
        done       = 1'b0;
        out_bytes  = 24'b0;

        case (state)
            IDLE: begin
                // Wait for in[3] to become 1
                if (in[3]) begin
                    next_state = BYTE1;
                    shift_reg  = {24{1'b0}}; // clear shift register
                end else begin
                    next_state = IDLE;
                end
            end

            BYTE1: begin
                // Capture first byte
                shift_reg = {in, shift_reg[23:8]};
                next_state = BYTE2;
            end

            BYTE2: begin
                // Capture second byte
                shift_reg = {in, shift_reg[23:8]};
                next_state = BYTE3;
            end

            BYTE3: begin
                // Capture third byte
                shift_reg = {in, shift_reg[23:8]};
                next_state = IDLE;
                done       = 1'b1;   // assert done in the cycle after third byte
            end
        endcase

        // Output is valid when done is asserted
        out_bytes = shift_reg;
    end

    // Sequential logic (flip-flops) triggered on positive edge of clk
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            done      <= 1'b0;
            out_bytes <= 24'b0;
        end else begin
            state <= next_state;
            // done and out_bytes are updated in the combinational block
            // based on the new state; here we just latch if needed,
            // but the always_comb drives them continuously.
            // To ensure done pulses exactly once per message,
            // we rely on the state machine transitioning back to IDLE.
        end
    end

endmodule

