module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        S_WALK_LEFT,      // 0
        S_WALK_RIGHT,     // 1
        S_FALLING,        // 2
        S_DIGGING,        // 3
        S_SPLATTERED      // 4
    } state_t;

    // State bits to track direction before falling/digging
    typedef enum logic [1:0] {
        DIR_LEFT,
        DIR_RIGHT
    } dir_t;

    // Internal signals
    state_t state, next_state;
    dir_t fall_dir, next_fall_dir;
    dir_t dig_dir, next_dig_dir;

    // Fall cycle counter
    logic [4:0] fall_counter, next_fall_counter;

    // Outputs (Moore machine)
    assign walk_left   = (state == S_WALK_LEFT);
    assign walk_right  = (state == S_WALK_RIGHT);
    assign aaah        = (state == S_FALLING);
    assign digging     = (state == S_DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_LEFT;
            fall_dir <= DIR_LEFT;
            dig_dir <= DIR_LEFT;
            fall_counter <= 5'd0;
        end else begin
            state <= next_state;
            fall_dir <= next_fall_dir;
            dig_dir <= next_dig_dir;
            fall_counter <= next_fall_counter;
        end
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;
        next_fall_dir = fall_dir;
        next_dig_dir = dig_dir;
        next_fall_counter = fall_counter;

        case (state)
            S_WALK_LEFT: begin
                if (!ground) begin
                    // Start falling, remember walking direction
                    next_state = S_FALLING;
                    next_fall_dir = DIR_LEFT;
                    next_fall_counter = 5'd1;
                end else if (dig && !bump_left && !bump_right) begin
                    // Can dig only if walking on ground, not bumped
                    next_state = S_DIGGING;
                    next_dig_dir = DIR_LEFT;
                end else begin
                    // Switch direction if bumped (higher precedence than nothing)
                    if (bump_left && !bump_right)
                        next_state = S_WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = S_WALK_LEFT;
                    // If bumped on both sides, still switch (chosen: right)
                    else if (bump_left && bump_right)
                        next_state = S_WALK_RIGHT;
                end
            end

            S_WALK_RIGHT: begin
                if (!ground) begin
                    next_state = S_FALLING;
                    next_fall_dir = DIR_RIGHT;
                    next_fall_counter = 5'd1;
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = S_DIGGING;
                    next_dig_dir = DIR_RIGHT;
                end else begin
                    if (bump_right && !bump_left)
                        next_state = S_WALK_LEFT;
                    else if (bump_left && !bump_right)
                        next_state = S_WALK_RIGHT;
                    else if (bump_left && bump_right)
                        next_state = S_WALK_LEFT; // Tie-break: left
                end
            end

            S_FALLING: begin
                if (ground) begin
                    // Ground reappeared
                    if (fall_counter >= 20) begin
                        // Splatter: fell for 20+ cycles
                        next_state = S_SPLATTERED;
                    end else begin
                        // Resume walking in original direction
                        if (fall_dir == DIR_LEFT)
                            next_state = S_WALK_LEFT;
                        else
                            next_state = S_WALK_RIGHT;
                    end
                    next_fall_counter = 5'd0;
                end else begin
                    // Still falling, increment counter
                    next_fall_counter = fall_counter + 5'd1;
                    // Stay in FALLING state
                end
            end

            S_DIGGING: begin
                if (!ground) begin
                    // Reached other side (ground went low while digging), fall
                    next_state = S_FALLING;
                    // Remember the direction we were walking before digging
                    next_fall_dir = dig_dir;
                    next_fall_counter = 5'd1;
                end else begin
                    // Continue digging
                    // Being bumped while digging has no effect
                    // Stay in DIGGING state
                end
            end

            S_SPLATTERED: begin
                // Forever stuck, only reset exits
                next_state = S_SPLATTERED;
                next_fall_counter = 5'd0;
            end
        endcase
    end

    // Assign outputs based on state
    // walk_left: 1 when state is S_WALK_LEFT
    // walk_right: 1 when state is S_WALK_RIGHT
    // aaah: 1 when state is S_FALLING
    // digging: 1 when state is S_DIGGING

endmodule

