module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for each row of the K-map
    // Row 00 (x[3:4] == 2'b00)
    wire r00_00, r00_01, r00_11, r00_10;
    // Row 01 (x[3:4] == 2'b01)
    wire r01_00, r01_01, r01_11, r01_10;
    // Row 11 (x[3:4] == 2'b11)
    wire r11_00, r11_01, r11_11, r11_10;
    // Row 10 (x[3:4] == 2'b10)
    wire r10_00, r10_01, r10_11, r10_10;

    // Decode the 4-bit input into the K-map rows and columns
    // x[3] is the most significant bit, x[0] is the least significant
    assign {r10_10, r10_11, r10_01, r10_00} = x;  // row 10
    assign {r11_10, r11_11, r11_01, r11_00} = x;  // row 11
    assign {r01_10, r01_11, r01_01, r01_00} = x;  // row 01
    assign {r00_10, r00_11, r00_01, r00_00} = x;  // row 00

    // Implement the function based on the K-map:
    // f = (x[3:4]==3'b11 & x[1:0]!=2'b00) | (x[3:4]==3'b10) | (x[3:4]==3'b01 & x[1:0]==2'b00)
    // Using the don't-care conditions to simplify:
    // When x[3:4] == 2'b11: f = 1 if x[1:0] != 2'b00, else 0 (don't-cares at 00 and 11 make it x|~x -> 1 for non-00)
    // When x[3:4] == 2'b10: f = 1 (all inputs covered, don't-care at 11 helps)
    // When x[3:4] == 2'b01: f = 1 if x[1:0] == 2'b11, else 0 (don't-care at 00 and 10 helps)
    // When x[3:4] == 2'b00: f = 0 (don't-cares everywhere allow pulling down to 0)

    // Simplified logic derived from K-map grouping:
    // Group 1: x[3:4] == 2'b11 & x[1:0] != 2'b00  -> x[3] & x[4] & ~(~x[1] & ~x[0]) ... better to use direct mux
    // Let's use a case statement for clarity and synthesisability.

    always_comb begin
        case ({x[3], x[4]})
            2'b11: f = (~x[1]) | x[0];  // row 11: 00->d, 01->1, 11->d, 10->0. Setting d=1 for 00 and 11 gives f = ~x[1] | x[0].
            2'b10: f = 1'b1;             // row 10: 00->1, 01->1, 11->d, 10->d. All are 1 or d. Set d=1 -> f=1.
            2'b01: f = x[1] & x[0];     // row 01: 00->0, 01->d, 11->1, 10->0. Setting d=0 for 01 and 10 gives f = x[1] & x[0].
            2'b00: f = 1'b0;             // row 00: all d. Setting d=0 -> f=0.
        endcase
    end

endmodule
